package practice;

import java.util.List;

/**
 * Renders thumbnails for uploaded images, one batch of uploads after another. It runs on a
 * thread of the service's render pool, which is shut down with shutdownNow() on every deploy.
 */
public class ThumbnailWorker {

    /** Renders one image; pure CPU work that never blocks. */
    public interface Renderer {
        void render(String image);
    }

    private final Renderer renderer;

    public ThumbnailWorker(Renderer renderer) {
        this.renderer = renderer;
    }

    /** Renders the batches in order and returns how many images it rendered. */
    public int renderAll(List<List<String>> batches) {
        int rendered = 0;
        for (List<String> batch : batches) {
            if (stopRequested()) break;
            rendered += renderBatch(batch);
        }
        return rendered;
    }

    /** Renders one batch and returns how many of its images it rendered. */
    int renderBatch(List<String> batch) {
        int rendered = 0;
        for (String image : batch) {
            if (stopRequested()) break;
            renderer.render(image);
            rendered++;
        }
        return rendered;
    }

    /** Whether this worker has been asked to stop. */
    boolean stopRequested() {
        return Thread.currentThread().isInterrupted();
    }
}

package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            List<List<String>> uploads = List.of(
                    List.of("hike-1.jpg", "hike-2.jpg", "hike-3.jpg"),
                    List.of("cat-5.png", "cat-6.png"));
            List<String> rendered = new ArrayList<>();
            int all = new ThumbnailWorker(rendered::add).renderAll(uploads);
            System.out.println("no stop request: rendered " + all + " " + rendered);
            rendered.clear();
            int some = new ThumbnailWorker(image -> {
                rendered.add(image);
                if (image.equals("hike-2.jpg")) Thread.currentThread().interrupt();
            }).renderAll(uploads);
            boolean callerSeesRequest = Thread.interrupted();
            System.out.println("stop asked during hike-2.jpg: rendered " + some + " " + rendered);
            System.out.println("caller can still see the request: " + callerSeesRequest);
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

